import * as React from "react";

export type SongTicketIconProps = React.SVGProps<SVGSVGElement> & { size?: number };

export function SongTicketIcon({ size = 20, ...props }: SongTicketIconProps) {
  return (
    <svg
      width={size}
      height={size}
      viewBox="0 0 24 24"
      fill="none"
      stroke="currentColor"
      strokeWidth="1.8"
      strokeLinecap="round"
      strokeLinejoin="round"
      aria-hidden="true"
      {...props}
    >
      <rect x="3.5" y="7" width="17" height="10" rx="1.5" /><path d="M10 14.5V10l4-1v4M12 7v10" />
    </svg>
  );
}
